seq="AAAAAAAAGCGCGCGGCGCGAAAGCGCAAGCGCGAAAGCGCAAGCGCGAAAGCGCCGCGCGCAAGCGGCGCGAAGCGCAAGCGCGAAGCGCAAGCGCGAAGCGCCGCAAAAAAAAA"
t='........(((((((((((....))))..((((....))))..((((....)))))))))))..(((((((...))))..((((...))))..((((...))))))).........'
# build pairs
stack=[]; pairs={}
for i,c in enumerate(t):
    if c=='(':
        stack.append(i)
    elif c==')':
        j=stack.pop(); pairs[(j,i)]=True
comp={'A':'U','U':'A','G':'C','C':'G'}
ok=True
for (i,j) in sorted(pairs):
    a,b=seq[i],seq[j]
    good = (comp[a]==b)
    if not good: print(f"pair {i},{j}: {a}-{b} BAD")
    ok = ok and good
print("all good:", ok)
